import zipfile, xml.etree.ElementTree as ET

NS = {'m': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
z = zipfile.ZipFile('budget.xlsx')
root = ET.fromstring(z.read('xl/worksheets/sheet1.xml'))

rows = []
for row in root.findall('.//m:sheetData/m:row', NS):
    rnum = int(row.get('r'))
    cells = {}
    for c in row.findall('m:c', NS):
        ref = c.get('r')
        t = c.get('t')
        v = c.find('m:v', NS)
        is_ = c.find('m:is', NS)
        if t == 'inlineStr' and is_ is not None:
            txt = ''.join(x.text or '' for x in is_.findall('.//m:t', NS))
            cells[ref] = txt
        elif v is not None:
            cells[ref] = v.text
        elif c.find('m:f', NS) is not None:
            f = c.find('m:f', NS)
            cells[ref] = '=' + (f.text or '')
    rows.append((rnum, cells))

for rnum, cells in rows:
    print(rnum, cells)
EOF
